# --- a minimal stand-in for the SDK's primitives (concepts, not the real lib) ---
def function_tool(fn):
    fn.tool_name = fn.__name__
    fn.tool_doc = (fn.__doc__ or "").strip()
    return fn

class Agent:
    def __init__(self, name, instructions, tools=None):
        self.name, self.instructions, self.tools = name, instructions, tools or []

class Runner:
    @staticmethod
    def run(agent, user_input):
        # a fake model 'decides' to call the first tool, then answers
        tool = agent.tools[0]
        observation = tool(invoice_id="INV-9")          # act
        return f"[{agent.name}] {observation}"           # final answer

@function_tool
def lookup_invoice(invoice_id: str) -> str:
