class Agent:
    def __init__(self, name, instructions, tools=None, handoffs=None):
        self.name = name
        self.instructions = instructions
        self.tools = tools or []
        self.handoffs = {a.name: a for a in (handoffs or [])}

class Runner:
    @staticmethod
    def run(agent, user_input):
        # fake 'classifier': triage decides which specialist to hand off to
        if agent.handoffs:
            target = "billing" if "charge" in user_input else "tech"
            agent = agent.handoffs[target]          # transfer control
        # the chosen agent now answers with its own instructions
        return f"[{agent.name}] {agent.instructions}"

billing = Agent("billing", "Handling your refund.")
tech = Agent("tech", "Helping with your login.")
triage = Agent("triage", "Route to a specialist.", handoffs=[billing, tech])

print(Runner.run(triage, "I was double-charged"))
print(Runner.run(triage, "I cannot log in"))

