def run_agent(agent, user_input, model, max_steps=5):
    # agent = {"instructions": str, "tools": {name: fn}}
    history = [{"role": "user", "content": user_input}]
    for _ in range(max_steps):
        step = model(agent["instructions"], history)   # reason
        if "final" in step:
            return step["final"]                        # done
        fn = agent["tools"][step["tool"]]               # act
        observation = fn(**step["args"])
        history.append({"role": "tool",
                        "name": step["tool"],
                        "content": observation})        # observe
    raise RuntimeError("agent did not converge within max_steps")

