from typing import Callable

def run(agent: dict, user_input: str, model: Callable, max_steps: int = 5) -> str:
    # agent = {"instructions": str, "tools": {name: fn}}
    history = [{"role": "user", "content": user_input}]
    for _ in range(max_steps):
        step = model(agent["instructions"], history)   # reason
        if "final" in step:
            return step["final"]                        # stop
        name, args = step["tool"], step.get("args", {})
        fn = agent["tools"][name]                       # act
        observation = fn(**args)
        history.append({"role": "tool", "name": name, "content": observation})  # observe
    raise RuntimeError("agent did not converge within max_steps")

if __name__ == "__main__":
    agent = {"instructions": "billing", "tools": {"paid": lambda invoice_id: f"{invoice_id}: paid"}}
    calls = iter([{"tool": "paid", "args": {"invoice_id": "INV-9"}}, {"final": "INV-9 is paid."}])
    print(run(agent, "status of INV-9?", lambda i, h: next(calls)))
